<section class="container section"><div class="section-header"><div><h1><?= e($cookbook['title']) ?></h1><p><?= e($cookbook['description']) ?></p><?php if (!empty($cookbook['share_token'])): ?><p class="muted">Share link: <a href="<?= e('/cookbook/shared/' . $cookbook['share_token']) ?>"><?= e(base_url() . '/cookbook/shared/' . $cookbook['share_token']) ?></a></p><?php endif; ?></div><?php if (empty($shared)): ?><a class="button" href="/cookbook/<?= e($cookbook['id']) ?>/edit">Edit cookbook</a><?php endif; ?></div><?php foreach ($cookbook['sections'] as $section): ?><details class="card cookbook-section" open><summary><?= e($section['title']) ?></summary><?php foreach ($section['recipes'] as $entry): ?><article class="cookbook-recipe"><?php if (!empty($entry['recipe'])): ?><h3><a href="/recipe/<?= e($entry['recipe']['id']) ?>"><?= e($entry['recipe']['title']) ?></a></h3><p class="muted">Scaled ×<?= e(format_quantity($entry['scale'] ?? 1)) ?></p><ul class="ingredient-list compact"><?php foreach ($entry['recipe']['ingredients'] as $ingredient): ?><li><?= e(format_quantity($ingredient['scaled_quantity'] ?? $ingredient['quantity'] ?? '')) ?> <?= e((string) ($ingredient['unit'] ?? '')) ?> <?= e((string) ($ingredient['name'] ?? '')) ?></li><?php endforeach; ?></ul><?php else: ?><p>Recipe no longer available.</p><?php endif; ?><?php if (!empty($entry['notes'])): ?><p><strong>Notes:</strong> <?= e($entry['notes']) ?></p><?php endif; ?></article><?php endforeach; ?></details><?php endforeach; ?></section>
